try {
	options.signal?.throwIfAborted();

	const result = await input(attemptNumber);

	options.signal?.throwIfAborted();

	return result;
} catch (error) {
	if (await onAttemptFailure({
		error,
		attemptNumber,
		retriesConsumed,
		startTime,
		options,
	})) {
		retriesConsumed++;
	} else {
		retriesConsumed = 0;
	}
}

} else {
	// Do not reset retriesConsumed when retry is not consumed
}

